sourcesContent:
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

import './Prediction.css';
import backgroundImage from '../assets/background.jpg';
import sunIcon from '../assets/sun.png';
import moonIcon from '../assets/moon.png';
import sendIcon from '../assets/send.png';

const translations = {
  en: {
    languageLabel: 'Language:',
    yes: 'yes',
    no: 'no',
    startOver: 'Start Over',
    home: '🏠 Home',
    visualization: '📊 Visualization',
    darkModeOn: 'Dark Mode',
    darkModeOff: 'Light Mode',
    typing: 'Typing...',
    questions: [
      "How old are you?",
      "What is your gender?",
      "What's your BMI (Body Mass Index)?",
      "What's your HbA1c Level (%)?",
      "What's your Blood Glucose Level (mg/dL)?",
      "Do you have hypertension?",
      "Do you have heart disease?",
      "What is your smoking history?"
    ],
    genderOptions: ['Female', 'Male', 'Other'],
    smokingOptions: ['never', 'former', 'current', 'not current', 'ever'],
    generalAdviceTitle: "🌟 General Tips:",
    generalAdvice: [
      '🩺 Monitor your blood sugar levels regularly.',
      '⚖️ Maintain a healthy weight.',
      '🏃 Stay physically active (at least 150 minutes/week).',
      '📅 Get regular check-ups with your doctor.',
    ],
    dietAdviceTitle: "🍎 Dietary Advice:",
    dietAdvice: [
      '🥦 Eat plenty of non-starchy vegetables.',
      '🌾 Choose whole grains over refined ones.',
      '🥤 Limit sugary drinks and juices.',
      '🥑 Include healthy fats like avocados and nuts.',
    ],
    warningSignsTitle: "⚠️ Watch for these warning signs:",
    warningSigns: [
      '🚽 Frequent urination.',
      '😰 Excessive thirst.',
      '📉 Unexplained weight loss.',
      '😴 Fatigue and blurred vision.',
    ],
    startMessage1: "Hi there! 👋 I'm your Diabetes Risk Assistant.",
    startMessage2: "Let's get started!",
    thankYou: "Thank you for your answers. Calculating your risk...",
    riskResult: (risk) => `Your predicted diabetes risk is: ${risk}`,
    fallbackRisk: (risk) => `Based on your inputs, your estimated risk is: ${risk}%`,
    adviceQuestion: "Would you like some advice on how to reduce diabetes risk?",
    adviceYesNo: ['yes', 'no'],
    pleaseYesNo: "Please answer 'yes' or 'no'.",
    pleaseChoose: (opts) => `Please choose one of: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Please enter a number between ${min} and ${max}`,
    alrightAdviceDeclined: "Alright, feel free to come back anytime if you need advice.",
    okayMoreAdvice: "Okay, feel free to ask for more advice anytime!",
    allAdviceDone: "That's all the advice for now. Stay healthy! 💙",
    consultDoctor: "Remember to consult with your doctor for personalized advice.",
  },

  fr: {
    languageLabel: 'Langue :',
    yes: 'oui',
    no: 'non',
    startOver: 'Recommencer',
    home: '🏠 Accueil',
    visualization: '📊 Visualisation',
    darkModeOn: 'Mode Sombre',
    darkModeOff: 'Mode Clair',
    typing: 'En train d\'écrire...',
    questions: [
      "Quel âge avez-vous ?",
      "Quel est votre genre ?",
      "Quel est votre IMC (Indice de Masse Corporelle) ?",
      "Quel est votre taux d'HbA1c (%) ?",
      "Quel est votre taux de glucose sanguin (mg/dL) ?",
      "Avez-vous de l'hypertension ?",
      "Avez-vous une maladie cardiaque ?",
      "Quel est votre historique tabagique ?"
    ],
    genderOptions: ['Femme', 'Homme', 'Autre'],
    smokingOptions: ['jamais', 'ancien', 'actuel', 'pas actuel', 'déjà fumé'],
    generalAdviceTitle: "🌟 Conseils généraux :",
    generalAdvice: [
      '🩺 Surveillez régulièrement votre glycémie.',
      '⚖️ Maintenez un poids sain.',
      '🏃 Restez physiquement actif (au moins 150 minutes/semaine).',
      '📅 Faites des contrôles réguliers chez votre médecin.',
    ],
    dietAdviceTitle: "🍎 Conseils diététiques :",
    dietAdvice: [
      '🥦 Mangez beaucoup de légumes non féculents.',
      '🌾 Choisissez des grains entiers plutôt que raffinés.',
      '🥤 Limitez les boissons sucrées et les jus.',
      '🥑 Incluez des graisses saines comme les avocats et les noix.',
    ],
    warningSignsTitle: "⚠️ Surveillez ces signes d'alerte :",
    warningSigns: [
      '🚽 Mictions fréquentes.',
      '😰 Soif excessive.',
      '📉 Perte de poids inexpliquée.',
      '😴 Fatigue et vision floue.',
    ],
    startMessage1: "Bonjour ! 👋 Je suis votre assistant pour le risque de diabète.",
    startMessage2: "Commençons !",
    thankYou: "Merci pour vos réponses. Calcul du risque...",
    riskResult: (risk) => `Votre risque de diabète prédit est : ${risk}`,
    fallbackRisk: (risk) => `Selon vos données, votre risque estimé est : ${risk}%`,
    adviceQuestion: "Souhaitez-vous des conseils pour réduire le risque de diabète ?",
    adviceYesNo: ['oui', 'non'],
    pleaseYesNo: "Veuillez répondre par 'oui' ou 'non'.",
    pleaseChoose: (opts) => `Veuillez choisir parmi : ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `Veuillez entrer un nombre entre ${min} et ${max}`,
    alrightAdviceDeclined: "D'accord, revenez quand vous voulez pour des conseils.",
    okayMoreAdvice: "D'accord, n'hésitez pas à demander plus de conseils !",
    allAdviceDone: "Voilà tous les conseils pour le moment. Restez en bonne santé ! 💙",
    consultDoctor: "N'oubliez pas de consulter votre médecin pour des conseils personnalisés.",
  },

  ar: {
    languageLabel: 'اللغة:',
    yes: 'نعم',
    no: 'لا',
    startOver: 'ابدأ من جديد',
    home: '🏠 الصفحة الرئيسية',
    visualization: '📊 التمثيل البياني',
    darkModeOn: 'الوضع الداكن',
    darkModeOff: 'الوضع الفاتح',
    typing: '...يكتب',
    questions: [
      "كم عمرك؟",
      "ما هو جنسك؟",
      "ما هو مؤشر كتلة الجسم (BMI) الخاص بك؟",
      "ما هو مستوى HbA1c (%) الخاص بك؟",
      "ما هو مستوى جلوكوز الدم (mg/dL) الخاص بك؟",
      "هل تعاني من ارتفاع ضغط الدم؟",
      "هل تعاني من أمراض القلب؟",
      "ما هو تاريخ تدخينك؟"
    ],
    genderOptions: ['أنثى', 'ذكر', 'آخر'],
    smokingOptions: ['أبدا', 'سابق', 'حالي', 'ليس حاليا', 'سبق'],
    generalAdviceTitle: "🌟 نصائح عامة:",
    generalAdvice: [
      '🩺 راقب مستويات السكر في الدم بانتظام.',
      '⚖️ حافظ على وزن صحي.',
      '🏃 كن نشيطاً بدنيا (150 دقيقة على الأقل في الأسبوع).',
      '📅 قم بالفحوصات الدورية مع طبيبك.',
    ],
    dietAdviceTitle: "🍎 نصائح غذائية:",
    dietAdvice: [
      '🥦 تناول الكثير من الخضروات غير النشوية.',
      '🌾 اختر الحبوب الكاملة بدلاً من المكررة.',
      '🥤 قلل من المشروبات والعصائر المحلاة.',
      '🥑 أدرج الدهون الصحية مثل الأفوكادو والمكسرات.',
    ],
    warningSignsTitle: "⚠️ راقب علامات التحذير التالية:",
    warningSigns: [
      '🚽 كثرة التبول.',
      '😰 العطش المفرط.',
      '📉 فقدان الوزن غير المبرر.',
      '😴 التعب وتشوش الرؤية.',
    ],
    startMessage1: "مرحباً! 👋 أنا مساعدك في تقييم خطر الإصابة بالسكري.",
    startMessage2: "لنبدأ!",
    thankYou: "شكراً لإجاباتك. جارٍ حساب الخطر...",
    riskResult: (risk) => `مخاطر الإصابة بالسكري المتوقعة لديك هي: ${risk}`,
    fallbackRisk: (risk) => `بناءً على مدخلاتك، تقدير المخاطر هو: ${risk}%`,
    adviceQuestion: "هل ترغب في بعض النصائح لتقليل خطر الإصابة بالسكري؟",
    adviceYesNo: ['نعم', 'لا'],
    pleaseYesNo: "يرجى الرد بـ 'نعم' أو 'لا'.",
    pleaseChoose: (opts) => `يرجى اختيار واحد من: ${opts.join(', ')}`,
    enterNumberBetween: (min, max) => `يرجى إدخال رقم بين ${min} و ${max}`,
    alrightAdviceDeclined: "حسناً، لا تتردد في العودة في أي وقت للحصول على نصائح.",
    okayMoreAdvice: "حسناً، لا تتردد في طلب المزيد من النصائح في أي وقت!",
    allAdviceDone: "هذا كل النصائح حتى الآن. حافظ على صحتك! 💙",
    consultDoctor: "تذكر استشارة طبيبك للحصول على نصائح شخصية.",
  }
};

const Prediction = ({ darkMode, setDarkMode }) => {
  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [currentStep, setCurrentStep] = useState(0);
  const [isTyping, setIsTyping] = useState(false);
  const [showOptions, setShowOptions] = useState([]);
  const [adviceStep, setAdviceStep] = useState(-1);
  const [showAdvice, setShowAdvice] = useState(false);
  const [adviceCompleted, setAdviceCompleted] = useState(false);
  const [language, setLanguage] = useState('en');
  const messagesEndRef = useRef(null);
  const navigate = useNavigate();

  const t = translations[language]; // current translations

  const questions = t.questions.map((q, index) => {
    switch (index) {
      case 1:
        return { question: q, type: 'options', options: t.genderOptions };
      case 6:
        return { question: q, type: 'boolean' };
      case 7:
        return { question: q, type: 'options', options: t.smokingOptions };
      default:
        return { question: q, type: 'input' };
    }
  });

  useEffect(() => {
    // On load, greet user in selected language and ask first question
    addMessage('bot', t.startMessage1);
    addMessage('bot', t.startMessage2);
    setTimeout(() => {
      addMessage('bot', questions[0].question);
      if (questions[0].type === 'options') setShowOptions(questions[0].options);
    }, 1500);
  }, [language]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const addMessage = (sender, text, options = null) => {
    setMessages(prev => [...prev, { sender, text, options }]);
    setShowOptions(options || []);
  };

  const handleInputChange = (e) => {
    setInputValue(e.target.value);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && inputValue.trim() !== '') {
      handleUserInput(inputValue.trim());
    }
  };

  const validateAnswer = (value, questionIndex) => {
    // Example validations (you can improve them)
    if (questionIndex === 0) {
      const num = Number(value);
      if (isNaN(num) || num < 0 || num > 120) {
        addMessage('bot', t.enterNumberBetween(0, 120));
        return false;
      }
    }
    if (questionIndex === 2) {
      const num = Number(value);
      if (isNaN(num) || num < 10 || num > 70) {
        addMessage('bot', t.enterNumberBetween(10, 70));
        return false;
      }
    }
    if (questionIndex === 3) {
      const num = Number(value);
      if (isNaN(num) || num < 3 || num > 20) {
        addMessage('bot', t.enterNumberBetween(3, 20));
        return false;
      }
    }
    if (questionIndex === 4) {
      const num = Number(value);
      if (isNaN(num) || num < 40 || num > 600) {
        addMessage('bot', t.enterNumberBetween(40, 600));
        return false;
      }
    }
    if (questionIndex === 5 || questionIndex === 6) {
      const valLower = value.toLowerCase();
      if (![t.yes, t.no].includes(valLower)) {
        addMessage('bot', t.pleaseYesNo);
        return false;
      }
    }
    if (questionIndex === 7) {
      if (!t.smokingOptions.includes(value)) {
        addMessage('bot', t.pleaseChoose(t.smokingOptions));
        return false;
      }
    }
    return true;
  };

  const handleUserInput = (value) => {
    if (!validateAnswer(value, currentStep)) return;
    addMessage('user', value);

    if (currentStep + 1 < questions.length) {
      const nextStep = currentStep + 1;
      setCurrentStep(nextStep);
      setIsTyping(true);
      setTimeout(() => {
        addMessage('bot', questions[nextStep].question, 
          questions[nextStep].type === 'options' ? questions[nextStep].options : 
          questions[nextStep].type === 'boolean' ? [t.yes, t.no] : null
        );
        setIsTyping(false);
      }, 800);
    } else {
      // End of questions: call API or fallback prediction
      addMessage('bot', t.thankYou);
      setIsTyping(true);

      // Dummy risk score generation for fallback
      const fallbackRiskScore = (Math.random() * 100).toFixed(2);

      setTimeout(() => {
        // Simulate API call here or fallback
        addMessage('bot', t.fallbackRisk(fallbackRiskScore));
        setIsTyping(false);
        setShowAdvice(true);
        setAdviceStep(0);
      }, 2000);
    }

    setInputValue('');
  };

  const handleOptionSelect = (option) => {
    handleUserInput(option);
  };

  // Advice flow data & handlers
  const adviceSections = [
    { title: t.generalAdviceTitle, items: t.generalAdvice },
    { title: t.dietAdviceTitle, items: t.dietAdvice },
    { title: t.warningSignsTitle, items: t.warningSigns },
  ];

  const handleAdviceNext = () => {
    if (adviceStep < adviceSections.length - 1) {
      setAdviceStep(adviceStep + 1);
    } else {
      setAdviceCompleted(true);
      setShowAdvice(false);
      addMessage('bot', t.consultDoctor);
    }
  };

  const handleAdviceSkip = () => {
    setAdviceCompleted(true);
    setShowAdvice(false);
    addMessage('bot', t.alrightAdviceDeclined);
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  return (
    <div
      className={`container ${darkMode ? 'dark' : 'light'}`}
      style={{
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        minHeight: '100vh',
        color: darkMode ? '#eee' : '#222',
        transition: 'all 0.3s ease',
      }}
    >
      {/* Navigation */}
      <div className="nav-bar" style={{ display: 'flex', gap: 15, padding: 15 }}>
        <button className="nav-button" onClick={() => navigate('/')}>{t.home}</button>
        <button className="nav-button" onClick={() => navigate('/visualization')}>{t.visualization}</button>
        
        {/* Language Selector */}
        <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 8 }}>
          <label htmlFor="language-select">{t.languageLabel}</label>
          <select
            id="language-select"
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
            style={{
              borderRadius: 12,
              border: 'none',
              padding: '5px 10px',
              cursor: 'pointer',
              background: darkMode ? '#444' : '#eee',
              color: darkMode ? '#eee' : '#222',
            }}
          >
            <option value="en">English</option>
            <option value="fr">Français</option>
            <option value="ar">العربية</option>
          </select>
        </div>

        {/* Dark Mode Toggle */}
        <button
          className="dark-mode-toggle"
          onClick={toggleDarkMode}
          style={{
            marginLeft: 15,
            cursor: 'pointer',
            background: 'transparent',
            border: 'none',
            outline: 'none',
          }}
          aria-label={darkMode ? t.darkModeOff : t.darkModeOn}
          title={darkMode ? t.darkModeOff : t.darkModeOn}
        >
          <img
            src={darkMode ? sunIcon : moonIcon}
            alt="Toggle Dark Mode"
            style={{ width: 24, height: 24 }}
          />
        </button>
      </div>

      {/* Chat messages */}
      <div
        className="chat-container"
        style={{
          maxWidth: 600,
          margin: 'auto',
          background: darkMode ? 'rgba(20, 20, 20, 0.75)' : 'rgba(255, 255, 255, 0.85)',
          borderRadius: 20,
          padding: 20,
          minHeight: 500,
          display: 'flex',
          flexDirection: 'column',
          boxShadow: darkMode
            ? '0 0 15px 5px rgba(255,255,255,0.1)'
            : '0 0 15px 5px rgba(0,0,0,0.1)',
          overflowY: 'auto',
        }}
      >
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`message ${msg.sender}`}
            style={{
              alignSelf: msg.sender === 'user' ? 'flex-end' : 'flex-start',
              background: msg.sender === 'user' ? (darkMode ? '#4A90E2' : '#1976d2') : (darkMode ? '#333' : '#eee'),
              color: msg.sender === 'user' ? '#fff' : (darkMode ? '#eee' : '#222'),
              borderRadius: 20,
              padding: 10,
              margin: '5px 0',
              maxWidth: '80%',
              wordWrap: 'break-word',
            }}
          >
            {msg.text}
            {msg.options && (
              <div style={{ marginTop: 10, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                {msg.options.map((opt, i) => (
                  <button
                    key={i}
                    onClick={() => handleOptionSelect(opt)}
                    className="option-button"
                    style={{
                      padding: '6px 12px',
                      borderRadius: 15,
                      border: 'none',
                      cursor: 'pointer',
                      background: darkMode ? '#555' : '#ddd',
                      color: darkMode ? '#eee' : '#222',
                      transition: 'background-color 0.3s',
                    }}
                    onMouseOver={e => (e.currentTarget.style.backgroundColor = darkMode ? '#777' : '#bbb')}
                    onMouseOut={e => (e.currentTarget.style.backgroundColor = darkMode ? '#555' : '#ddd')}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}

        {isTyping && (
          <div
            className="typing-indicator"
            style={{
              alignSelf: 'flex-start',
              fontStyle: 'italic',
              color: darkMode ? '#ccc' : '#666',
              marginTop: 5,
            }}
          >
            {t.typing}
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input area */}
      {!showAdvice && (
        <div
          className="input-container"
          style={{
            maxWidth: 600,
            margin: '20px auto',
            display: 'flex',
            gap: 10,
          }}
        >
          <input
            type="text"
            placeholder={t.questions[currentStep]}
            value={inputValue}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            disabled={showOptions.length > 0}
            style={{
              flex: 1,
              padding: '10px 15px',
              borderRadius: 20,
              border: 'none',
              outline: 'none',
              fontSize: 16,
              background: darkMode ? '#222' : '#fff',
              color: darkMode ? '#eee' : '#222',
              boxShadow: darkMode ? '0 0 5px #555' : '0 0 5px #ccc',
            }}
          />
          <button
            onClick={() => {
              if (inputValue.trim() !== '') handleUserInput(inputValue.trim());
            }}
            style={{
              background: 'transparent',
              border: 'none',
              cursor: 'pointer',
              padding: 0,
            }}
            aria-label="Send"
          >
            <img
              src={sendIcon}
              alt="Send"
              style={{ width: 32, height: 32, filter: darkMode ? 'invert(1)' : 'none' }}
            />
          </button>
        </div>
      )}

      {/* Advice flow */}
      {showAdvice && !adviceCompleted && (
        <div
          className="advice-container"
          style={{
            maxWidth: 600,
            margin: '20px auto',
            background: darkMode ? 'rgba(20, 20, 20, 0.85)' : 'rgba(255, 255, 255, 0.95)',
            borderRadius: 20,
            padding: 20,
            boxShadow: darkMode
              ? '0 0 15px 5px rgba(255,255,255,0.1)'
              : '0 0 15px 5px rgba(0,0,0,0.1)',
            color: darkMode ? '#eee' : '#222',
          }}
        >
          <h3>{adviceSections[adviceStep].title}</h3>
          <ul>
            {adviceSections[adviceStep].items.map((item, i) => (
              <li key={i} style={{ marginBottom: 8 }}>
                {item}
              </li>
            ))}
          </ul>
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 10 }}>
            <button
              onClick={handleAdviceSkip}
              style={{
                background: 'transparent',
                border: '1px solid',
                borderColor: darkMode ? '#aaa' : '#333',
                borderRadius: 15,
                padding: '6px 12px',
                cursor: 'pointer',
                color: darkMode ? '#eee' : '#222',
              }}
            >
              Skip
            </button>
            <button
              onClick={handleAdviceNext}
              style={{
                background: darkMode ? '#4A90E2' : '#1976d2',
                border: 'none',
                borderRadius: 15,
                padding: '6px 12px',
                cursor: 'pointer',
                color: '#fff',
              }}
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* Advice done message */}
      {adviceCompleted && (
        <div
          style={{
            maxWidth: 600,
            margin: '20px auto',
            padding: 20,
            textAlign: 'center',
            color: darkMode ? '#eee' : '#222',
          }}
        >
          {t.allAdviceDone}
        </div>
      )}
    </div>
  );
};

export default Prediction;
